const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = input[0];
let sum = 0;
const stack = [];

for (let i = 1; i <= n; i++) {
  const x = input[i];
  if (x === 0) {
    sum -= stack.pop();
  } else {
    stack.push(x);
    sum += x;
  }
}

console.log(sum);
